nextflow_process {

    name "Test Process TABIX_BGZIPTABIX"
    script "../main.nf"
    process "TABIX_BGZIPTABIX"

    tag "modules"
    tag "modules_nfcore"
    tag "tabix"
    tag "tabix/bgziptabix"

    test("deprecated") {

        when {
            process {
                """
                input[0] = [ [ id:'test' ], file('input') ]
                """
            }
        }

        then {
            assertAll(
                { assert process.failed },
                { assert process.errorReport.contains("WARNING: This module has been deprecated. Please use nf-core/modules/htslib/bgziptabix instead.") }
            )
        }
    }
}
